require "rails_helper"

# Runs outside the per-example transaction, because export opens its own
# repeatable read transaction.
RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  # "Replay the stored answer: the operation row for prepare, the receipt for the other operations."
  it "a detach_entries retried after a checkpoint round trip replays its receipt and keeps the agent assigned since" do
    connection = ActiveRecord::Base.connection
    store = described_class.new(connection:)
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: create(:user).id, project_id: project.id, work_date: Date.current,
      duration: 60.0, note: "", bill_status: "unbilled", agent_id: 77
    )
    actor = Timekeeping::LocalOwner::Actor.service(name: "agent-destroy", company_id: company.id,
                                                   operations: %w[agents.detach_entries])
    detach = lambda do
      Timekeeping::LocalOwner.call(
        operation: :detach_entries, company_id: company.id, generation: generation.to_s, actor:,
        params: { "agent_id" => 77, "body" => { "operation_id" => "8a3c1f2e-5b6d-4e7f-9a0b-1c2d3e4f5a6b", "generation" => generation } }
      )
    end
    first = detach.call
    expect([first.status, first.body]).to eq([200, { "detached" => 1 }])
    entry.update_columns(agent_id: 77)

    checkpoint = store.export_checkpoint
    expect(checkpoint.rows.fetch("service_idempotency_receipts").size).to eq(1)
    connection.execute("DELETE FROM service_idempotency_receipts")
    store.load_checkpoint(checkpoint)
    retried = detach.call

    expect([retried.status, retried.body]).to eq([200, { "detached" => 1 }])
    expect(Timekeeping::LocalEntry.find(entry.id).agent_id).to eq(77)
    expect(connection.select_value("SELECT COUNT(*) FROM service_idempotency_receipts").to_i).to eq(1)
  end
end

require "rails_helper"

RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  # "Replay the stored answer: the operation row for prepare, the receipt for the other operations."
  # A service receipt that a cutover dropped would let a retried detach_entries run a second time.
  it "monolith store carries service receipts through a checkpoint and leaves idempotency_records rows alone" do
    connection = ActiveRecord::Base.connection
    store = described_class.new(connection:)
    stamp = Time.utc(2026, 4, 2, 10, 15, 30, 654_321)
    connection.execute(ActiveRecord::Base.sanitize_sql_array([<<~SQL.squish, stamp]))
      INSERT INTO service_idempotency_receipts (company_id, actor_name, operation, key, fingerprint, status, body, created_at)
      VALUES (1, 'agent-destroy', 'detach_entries 77', '6f1c1f1e-0000-4000-8000-000000000001', 'abc', 200,
              '{"detached":1}', ?)
    SQL

    checkpoint = store.export_checkpoint

    rows = checkpoint.rows.fetch("service_idempotency_receipts")
    expect(rows.size).to eq(1)
    expect(rows.first).to include("company_id" => 1, "actor_name" => "agent-destroy", "operation" => "detach_entries 77",
                                  "key" => "6f1c1f1e-0000-4000-8000-000000000001", "status" => 200, "body" => '{"detached":1}')
    expect(checkpoint.rows.fetch("idempotency_records")).to eq([])

    connection.execute("DELETE FROM service_idempotency_receipts")
    store.load_checkpoint(checkpoint)

    expect(connection.select_rows("SELECT company_id, actor_name, operation, key, status, body FROM service_idempotency_receipts"))
      .to eq([[1, "agent-destroy", "detach_entries 77", "6f1c1f1e-0000-4000-8000-000000000001", 200, '{"detached":1}']])
    expect(connection.select_value("SELECT COUNT(*) FROM idempotency_records").to_i).to eq(0)
  ensure
    ActiveRecord::Base.connection.execute("DELETE FROM service_idempotency_receipts")
  end
end

require "rails_helper"

# Runs outside the per-example transaction, as the store's own spec does, because
# export and load open transactions with their own isolation level.
RSpec.describe Timekeeping::Handoff::MonolithStore, "service receipts across a cutover", :without_transaction do
  # "Replay the stored answer: the operation row for prepare, the receipt for the other operations."
  # "detach_entries clears one agent on the caller company's entries only."
  it "a detach_entries retried after a checkpoint round trip replays and keeps an agent assigned after the first detach" do
    connection = ActiveRecord::Base.connection
    ownership = TimekeepingOwnership.current
    saved = ownership.attributes.slice("owner", "monolith_store", "handoff_step")
    ownership.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    begin
      company_id = 4_242
      agent_id = 77
      entry_id = connection.select_value(<<~SQL.squish)
        INSERT INTO entries (company_id, project_id, user_id, agent_id, work_date, duration, bill_status, created_at, updated_at)
        VALUES (#{company_id}, 1, 1, #{agent_id}, CURRENT_DATE, 60.0, 'unbilled', now(), now()) RETURNING id
      SQL
      generation = TimekeepingOwnership.current.generation
      service = Timekeeping::LocalOwner::Actor.service(name: "agent-destroy", company_id:,
                                                       operations: %w[agents.detach_entries])
      operation_id = SecureRandom.uuid
      detach = lambda do
        Timekeeping::LocalOwner.call(
          operation: :detach_entries, company_id:, generation: generation.to_s, actor: service,
          params: { "agent_id" => agent_id, "body" => { "operation_id" => operation_id, "generation" => generation } }
        )
      end
      first = detach.call
      expect([first.status, first.body]).to eq([200, { "detached" => 1 }])

      # A user assigns the same agent again after the detach.
      connection.execute("UPDATE entries SET agent_id = #{agent_id}, version = version + 1 WHERE id = #{entry_id}")
      store = described_class.new(connection:)
      checkpoint = store.export_checkpoint
      # The other side of a cutover starts without this database's receipts.
      connection.execute("DELETE FROM service_idempotency_receipts")
      store.load_checkpoint(checkpoint)

      retried = detach.call

      expect([retried.status, retried.body]).to eq([200, { "detached" => 1 }])
      expect(connection.select_value("SELECT agent_id FROM entries WHERE id = #{entry_id}")).to eq(agent_id)
    ensure
      %w[service_idempotency_receipts entry_audits entry_outbox_items reservations invoice_operations entries]
        .each { |table| connection.execute("DELETE FROM #{table}") }
      ownership.reload.update!(saved)
    end
  end
end
